#!/bin/bash
# Corregir expo-av tsconfig automáticamente después de npm install

EXPO_AV_TSCONFIG="node_modules/expo-av/tsconfig.json"

if [ -f "$EXPO_AV_TSCONFIG" ]; then
  # Reemplazar el contenido del archivo
  cat > "$EXPO_AV_TSCONFIG" << 'EOF'
// @generated by expo-module-scripts
{
  "extends": "expo-module-scripts/tsconfig.base",
  "compilerOptions": {
    "rootDir": "./src",
    "outDir": "./build",
    "declaration": true,
    "declarationDir": "./build",
    "tsBuildInfoFile": "./build/.tsbuildinfo"
  },
  "include": ["./src"],
  "exclude": ["**/__mocks__/*", "**/__tests__/*", "**/__rsc_tests__/*"]
}
EOF
  echo "✅ expo-av tsconfig.json corregido"
fi
